survival_backtest<-function(predicted_event_curves,observations,horizons,censoring,design,uncertainty,cluster_resamples=NULL,confidence_level=.95,context=NULL){
 d<-.vb_design(design,context);if(d$target$conditioning!='performing') .cr_error('VALIDATION_TARGET','Event curves require performing cohort');factor<-.vb_number(d$days_per_time_unit,'days_per_time_unit',0);allowed<-list(days=1,months=c(30,365/12,365.25/12),years=c(365,365.25));if(!(factor%in%allowed[[d$target$time_unit]])) .cr_error('VALIDATION_TIME','Declare supported elapsed-day basis');dated<-d;dated$target$time_unit<-'days';dated$target$horizon<-ceiling(d$target$horizon*factor);rows<-.vb_records(observations,dated);h<-.vb_vec(horizons,'horizons');if(!length(rows)&&length(predicted_event_curves)) .cr_error('VALIDATION_SURVIVAL','Empty cohort requires empty curves');p<-if(!length(rows))matrix(numeric(),0,length(h))else .ex_matrix(predicted_event_curves,'predicted_event_curves');if(any(h<=0)||any(diff(h)<=0)||tail(h,1)>d$target$horizon||!identical(dim(p),c(length(rows),length(h)))||any(p<0|p>1)||(ncol(p)>1L&&any(p[,-1,drop=FALSE]<p[,-ncol(p),drop=FALSE]))) .cr_error('VALIDATION_SURVIVAL','Increasing horizons and aligned nondecreasing cumulative PDs required')
 spec<-.ex_object(censoring,'censoring');method<-spec$method;.vb_string(spec$reference,'censoring reference');if(!(method%in%c('complete_followup','frozen_ipcw'))) .cr_error('VALIDATION_CENSORING','Use complete_followup or frozen_ipcw');times<-vapply(rows,function(r).vb_number(r$observed_time,'observed_time',0),numeric(1));if(any(!vapply(rows,function(r)is.logical(r$event)&&length(r$event)==1L&&!is.na(r$event),logical(1)))) .cr_error('VALIDATION_EVENT','Boolean event indicators required');events<-vapply(rows,function(r)r$event,logical(1));eligible<-rep(1,length(rows));exclusions<-list()
 for(i in seq_along(rows)){row<-rows[[i]];known<-row$outcome_known_at;reason<-NULL;if(is.null(known))reason<-'OUTCOME_UNKNOWN'else if(.cr_data_date(known,'outcome_known_at')>.cr_data_date(d$evaluation_cutoff,'evaluation_cutoff'))reason<-'OUTCOME_NOT_YET_KNOWN'else if(.cr_data_date(known,'outcome_known_at')<.cr_data_date(row$as_of,'as_of')+ceiling(times[i]*factor)) .cr_error('VALIDATION_LOOKAHEAD','Followup cannot be known before elapsed time');if(!is.null(reason)){eligible[i]<-0;exclusions[[length(exclusions)+1L]]<-list(prediction_id=row$prediction_id,reason=reason)}}
 if(method=='frozen_ipcw'){
 if(!identical(spec$independence_assumption,'censoring_independent_of_event_features_and_across_clusters')||!identical(spec$tie_rule,'event_before_censoring')) .cr_error('VALIDATION_CENSORING','Marginal independent censoring and event-priority ties required');.vb_string(spec$model_fingerprint,'censoring model fingerprint');known<-.cr_data_date(spec$model_known_at,'model known_at');if(any(vapply(rows,function(r)known>.cr_data_date(r$as_of,'as_of'),logical(1)))) .cr_error('VALIDATION_LOOKAHEAD','Censoring model must precede forecasts');knots<-.vb_vec(spec$times,'censoring times',TRUE);survival<-.vb_vec(spec$survival,'censoring survival',TRUE);support<-.vb_number(spec$support_end,'support_end',0);minimum<-.vb_number(spec$minimum_survival,'minimum survival');if(minimum<=0||minimum>=1||length(knots)!=length(survival)||any(knots<0)||any(diff(knots)<=0)||any(survival<0|survival>1)||any(diff(survival)>0)||(length(knots)&&tail(knots,1)>support)) .cr_error('VALIDATION_CENSORING','Valid nonincreasing survival and positivity support required');G<-function(t,left=FALSE)vapply(t,function(z){index<-sum(if(left)knots<z else knots<=z);c(1,survival)[index+1L]},numeric(1))
 }else{support<-tail(h,1);minimum<-0;if(any(!events&times<=tail(h,1)&eligible>0)) .cr_error('VALIDATION_CENSORING','Complete nonevent followup must extend strictly beyond final horizon');G<-function(t,left=FALSE)rep(1,length(t))}
 gl<-G(times,TRUE);gr<-G(times,FALSE);gh<-G(h,FALSE);draws<-.vb_draws(uncertainty,cluster_resamples,rows,confidence_level);clusters<-vapply(rows,function(r)r$cluster_id,character(1));n<-length(rows)
 calculate<-function(multiplicity){mass<-eligible*multiplicity;N<-sum(mass);out<-list()
 for(j in seq_along(h)){tau<-h[j];cases<-events&times<=tau&mass>0;controls<-times>tau&mass>0;supported<-tau<=support&&gh[j]>minimum&&all(gl[cases]>minimum);reason<-if(N==0)'NO_ELIGIBLE_OBSERVATIONS'else if(!supported)'INSUFFICIENT_CENSORING_SUPPORT'else NULL
 if(!is.null(reason)){out[[j]]<-list(horizon=tau,brier=NULL,auc=NULL,applicability='NOT_APPLICABLE',reason=reason,case_count=sum(cases),control_count=sum(controls),censored_by_horizon=sum(!events&times<=tau&mass>0),ipcw_effective_sample_size=NULL,brier_contributions=NULL,auc_pair_mass=NULL);next}
 weights<-numeric(n);weights[cases]<-mass[cases]/gl[cases];weights[controls]<-mass[controls]/gh[j];if(any(!is.finite(weights))||!is.finite(sum(weights))) .cr_error('VALIDATION_NUMERICAL','IPCW exceeds finite range');if(sum(weights)==0){out[[j]]<-list(horizon=tau,brier=NULL,auc=NULL,applicability='NOT_APPLICABLE',reason='NO_OBSERVED_HORIZON_LABELS',case_count=0L,control_count=0L,censored_by_horizon=sum(!events&times<=tau&mass>0),ipcw_effective_sample_size=NULL,brier_contributions=NULL,auc_pair_mass=NULL);next};contributions<-weights*(as.numeric(cases)-p[,j])^2/N;num<-den<-0
 for(i in which(cases)){js<-which(controls&clusters!=clusters[i]);pair<-weights[i]*weights[js];num<-num+sum(pair*((p[i,j]>p[js,j])+.5*(p[i,j]==p[js,j])));den<-den+sum(pair)};if(!is.finite(num+den)) .cr_error('VALIDATION_NUMERICAL','AUC IPCW pair weights exceed finite range');normalized<-weights/sum(weights);out[[j]]<-list(horizon=tau,brier=sum(contributions),auc=if(den==0)NULL else num/den,applicability='APPLICABLE',reason=NULL,case_count=sum(cases),control_count=sum(controls),censored_by_horizon=sum(!events&times<=tau&mass>0),ipcw_effective_sample_size=1/sum(normalized^2),brier_contributions=as.list(contributions),auc_pair_mass=den,auc_applicability=if(den>0)'APPLICABLE'else'NOT_APPLICABLE',auc_reason=if(den>0)NULL else'NO_CROSS_CLUSTER_CASE_CONTROL_PAIRS')
 }
 tau<-tail(h,1);cases<-events&times<=tau&mass>0;good<-tau<=support&&all(gl[cases]>minimum)&&all(gr[cases]>minimum);num<-den<-0;pairs<-0L;if(good){for(i in which(cases)){js<-which(times>times[i]&mass>0&clusters!=clusters[i]);weight<-mass[i]*mass[js]/(gl[i]*gr[i]);num<-num+sum(weight*((p[i,ncol(p)]>p[js,ncol(p)])+.5*(p[i,ncol(p)]==p[js,ncol(p)])));den<-den+sum(weight);pairs<-pairs+length(js)};if(!is.finite(num+den)) .cr_error('VALIDATION_NUMERICAL','Concordance IPCW exceeds support')}
 concordance<-list(value=if(good&&den>0)num/den else NULL,applicability=if(good&&den>0)'APPLICABLE'else'NOT_APPLICABLE',reason=if(good&&den>0)NULL else if(!good)'INSUFFICIENT_CENSORING_SUPPORT'else'NO_CROSS_CLUSTER_COMPARABLE_PAIRS',tau=tau,pair_count=pairs,pair_mass=if(good)den else NULL,risk_score_horizon=tau);values<-lapply(out,function(r)r$brier);integrated<-if(length(h)>1L&&all(lengths(values)==1L)){v<-unlist(values);sum(diff(h)*(v[-1]+v[-length(v)])/2)/(tail(h,1)-h[1])}else NULL;list(by_horizon=out,concordance=concordance,integrated_brier=integrated,integration_interval=list(h[1],tail(h,1)),integration_rule='TRAPEZOID_ON_SUPPLIED_GRID_NOT_EXACT_CONTINUOUS_INTEGRAL')
 }
 metrics<-calculate(rep(1,n));samples<-if(is.null(draws))NULL else lapply(draws,function(draw){m<-calculate(draw);flat<-list(integrated_brier=m$integrated_brier,concordance=m$concordance$value);for(j in seq_along(m$by_horizon)){flat[paste0('brier_',j-1L)]<-list(m$by_horizon[[j]]$brier);flat[paste0('auc_',j-1L)]<-list(m$by_horizon[[j]]$auc)};flat})
 diagnostics<-list(censoring=spec,days_per_time_unit=factor,horizon_censoring_rule='CONTROLS_REQUIRE_OBSERVED_TIME_STRICTLY_GREATER_THAN_HORIZON',event_weight='1/G(event_time_left)',control_weight='1/G(horizon_right)',concordance_pair_weight='1/(G(event_time_left)*G(event_time_right)); continuous-censoring limit is Uno 1/G^2',pair_population='DIFFERENT_DECLARED_SAMPLING_CLUSTERS',score_ties='HALF_CREDIT',event_time_ties='NOT_COMPARABLE',brier_denominator='TOTAL_ELIGIBLE_MULTIPLICITY_NOT_SUM_OF_IPCW',censoring_estimation_uncertainty='NOT_INCLUDED',prediction_fingerprint=.cr_hash(.ex_rows(p)));result<-.vb_result('survival_backtest',metrics,d,rows,exclusions,.vb_bands(samples,confidence_level),context,diagnostics,'survival_validation');if(all(vapply(metrics$by_horizon,function(r)is.null(r$brier),logical(1)))&&is.null(metrics$concordance$value)){result$value$applicability<-'NOT_APPLICABLE';result$value$reason<-'NO_SUPPORTED_SURVIVAL_METRIC'};result
}
